<?php require_once "../db.php";require_role("Teacher");$uid=current_id();$st=$conn->prepare("SELECT * FROM teacher WHERE id=?");$st->bind_param("i",$uid);$st->execute();$u=$st->get_result()->fetch_assoc();if($_SERVER["REQUEST_METHOD"]==="POST"){$name=trim($_POST["name"]);$subject=trim($_POST["subject"]);$x=$conn->prepare("UPDATE teacher SET name=?,subject=? WHERE id=?");$x->bind_param("ssi",$name,$subject,$uid);$x->execute();$_SESSION["user_name"]=$name;$u["name"]=$name;$u["subject"]=$subject;}?>
